import json
import hashlib
import sqlite3
from pathlib import Path

MCP = "enablon_esg_controls"
PROCEDURE_ID = "TP-AZ-2024-006"
CONTROL_ID = "CTL-AZ-2024-004"
EXCEPTION_ID = "GRC-EXC-2024-017"


def _db(ws, backup=False):
    name = "state.db.pinned_backup" if backup else "state.db"
    return Path(ws).resolve().parent / "system" / MCP / name


def _rows(path, table, where="", params=()):
    con = sqlite3.connect(f"file:{path}?mode=ro", uri=True)
    con.row_factory = sqlite3.Row
    try:
        sql = f'SELECT * FROM "{table}"' + (f" WHERE {where}" if where else "")
        try:
            return [dict(row) for row in con.execute(sql, params).fetchall()]
        except sqlite3.OperationalError:
            return []
    finally:
        con.close()


def _norm_rows(rows):
    return sorted(json.dumps(row, sort_keys=True, separators=(",", ":")) for row in rows)


def check_approved_failed_result(ws):
    baseline = _rows(_db(ws, backup=True), "control_test_results", "test_procedure_id = ?", (PROCEDURE_ID,))
    current = _rows(_db(ws), "control_test_results", "test_procedure_id = ?", (PROCEDURE_ID,))
    old = {json.dumps(row, sort_keys=True, separators=(",", ":")) for row in baseline}
    added = [row for row in current if json.dumps(row, sort_keys=True, separators=(",", ":")) not in old]
    problems = []
    if len(added) != 1:
        problems.append(f"expected one new result for {PROCEDURE_ID}, found {len(added)}")
        return {"score": 0, "detail": "; ".join(problems)}
    row = added[0]
    expected = {
        "test_procedure_id": PROCEDURE_ID,
        "control_id": CONTROL_ID,
        "exception_id": EXCEPTION_ID,
        "test_conclusion": "FAILED",
        "sample_size": 18,
        "exceptions_found": 1,
        "tested_value_tco2e": 3751482,
        "population_total_tco2e": 5897822,
        "metric_basis_code": "2024_GROSS_SCOPE3_SELECTED_CONCENTRATION",
        "evidence_retrieval_status": "PENDING",
        "reliance_status": "FOLLOW_UP_REQUIRED",
    }
    for field, value in expected.items():
        if field == "evidence_retrieval_status":
            if row.get(field) not in {"PENDING", "AVAILABLE"}:
                problems.append(f"{field}={row.get(field)!r}, expected PENDING or AVAILABLE")
        elif field == "reliance_status":
            if row.get(field) not in {"FOLLOW_UP_REQUIRED", "NOT_RELIABLE"}:
                problems.append(f"{field}={row.get(field)!r}, expected FOLLOW_UP_REQUIRED or NOT_RELIABLE")
        elif row.get(field) != value:
            problems.append(f"{field}={row.get(field)!r}, expected {value!r}")
    if not row.get("test_result_id") or any(row["test_result_id"] == old_row.get("test_result_id") for old_row in baseline):
        problems.append("test_result_id is missing or not new")
    if not row.get("tested_on") or not row.get("tested_by_id") or not row.get("tested_by_display"):
        problems.append("tester/date context is incomplete")
    if not row.get("approved_at"):
        problems.append("approved_at is missing")
    comment = (row.get("auditor_comment") or "").lower()
    if "supplier" not in comment:
        problems.append("auditor_comment lacks supplier-data rationale")
    if not any(token in comment for token in ("incomplete", "outstanding", "missing", "pending")):
        problems.append("auditor_comment lacks incomplete/pending evidence rationale")
    if not any(token in comment for token in ("follow", "withheld", "reliance")):
        problems.append("auditor_comment lacks follow-up/reliance rationale")
    return {"score": 0 if problems else 1, "detail": "; ".join(problems) or "New approved failed result matches the required Category 1 control-test state."}


def check_idempotency_binding(ws):
    current_results = _rows(_db(ws), "control_test_results", "test_procedure_id = ?", (PROCEDURE_ID,))
    baseline_results = _rows(_db(ws, backup=True), "control_test_results", "test_procedure_id = ?", (PROCEDURE_ID,))
    old_ids = {row["test_result_id"] for row in baseline_results}
    added = [row for row in current_results if row["test_result_id"] not in old_ids]
    problems = []
    if len(added) != 1:
        return {"score": 0, "detail": "Cannot identify exactly one new result."}
    result_id = added[0]["test_result_id"]
    records = _rows(_db(ws), "control_test_result_idempotency", "test_result_id = ?", (result_id,))
    if len(records) != 1:
        problems.append(f"expected one idempotency record for {result_id}, found {len(records)}")
    else:
        record = records[0]
        if not (record.get("idempotency_key") or "").strip():
            problems.append("idempotency_key is empty")
        fingerprint = "\x1f".join("" if added[0].get(field) is None else str(added[0][field]) for field in (
            "test_result_id", "test_procedure_id", "control_id", "exception_id", "test_conclusion", "tested_on",
            "tested_by_id", "tested_by_display", "sample_size", "exceptions_found", "tested_value_tco2e",
            "population_total_tco2e", "metric_basis_code", "evidence_record_id", "evidence_retrieval_status",
            "reliance_status", "auditor_comment", "approved_at"))
        if record.get("payload_fingerprint") != fingerprint:
            problems.append("idempotency payload fingerprint does not match the new result")
    return {"score": 0 if problems else 1, "detail": "; ".join(problems) or "Idempotency record is non-empty and bound to the new result payload."}


def check_prior_records_unchanged(ws):
    current = _rows(_db(ws), "control_test_results")
    baseline_digest = "bc94f674e93087e94fb7ffafa241377dbfc26113f1e9453fe7b5f3cca704a21d"
    problems = []
    target_rows = _rows(_db(ws), "control_test_results", "test_procedure_id = ?", (PROCEDURE_ID,))
    added = [row for row in target_rows if row.get("test_result_id") != "TR-AZ-2025-006"]
    retained = [row for row in current if not added or row.get("test_result_id") != added[0].get("test_result_id")]
    digest = hashlib.sha256("|".join(_norm_rows(retained)).encode()).hexdigest()
    if digest != baseline_digest:
        problems.append("one or more pre-existing test results changed")
    if len(added) != 1:
        problems.append(f"expected one new result row, found {len(added)}")
    return {"score": 0 if problems else 1, "detail": "; ".join(problems) or "All pre-existing Enablon test results are unchanged."}

